    z_t1120_t _r = {0};
    int64_t idx = z_t2575_find(_this, _key, NULL);
    if (idx >= 0) {
        _r.tag = Z_OPTIONVIEWVAL_NAMEID_TAG_SOME;
        _r.data = &_this->entries[idx].value;
    } else {
        _r.tag = Z_OPTIONVIEWVAL_NAMEID_TAG_NONE;
        _r.data = NULL;
    }
    return _r;
